VALID_TRANSITIONS = {
    'new': ['ready'],
    'ready': ['running'],
    'running': ['waiting', 'terminated', 'ready'],
    'waiting': ['ready'],
    'terminated': []
}

def transition(self, new_state):
    if new_state not in VALID_TRANSITIONS[self.state]:
        raise ValueError(f'Invalid: {self.state} → {new_state}')
    self.state = new_state
